<script setup lang="ts">import {Head,Link} from '@inertiajs/vue3';import StoreLayout from '../Layouts/StoreLayout.vue';defineProps<{category:any,products:any[]}>();const image=(product:any)=>product.media?.find((m:any)=>m.type==='image')?.url||product.image_url;const asset=(url:string)=>url?.startsWith('http')?url:`/storage/${url}`;</script>
<template><Head><title>{{category.seo_title||category.name}}</title><meta name="description" :content="category.seo_description||category.description"/><link rel="canonical" :href="`http://localhost/categories/${category.slug}`"/></Head><StoreLayout><section class="page-head catalog-head"><p class="eyebrow">КАТАЛОГ LAMARI</p><h1>{{category.name}}</h1><p>{{category.description}}</p><div class="subcategories" v-if="category.children?.length"><Link v-for="child in category.children" :href="`/categories/${child.slug}`">{{child.name}}</Link></div></section><div class="catalog-tools"><span>{{products.length}} товарів</span><button>Фільтри +</button><span>За новизною ↓</span></div><section v-if="products.length" class="product-catalog"><Link v-for="product in products" :key="product.id" :href="`/products/${product.slug}`" class="catalog-card"><div class="catalog-image"><img :src="asset(image(product))" :alt="product.name"><span v-if="product.media?.some((m:any)=>m.type==='video')" class="video-badge">▶ Відео</span></div><h3>{{product.name}}</h3><p>{{(product.variants[0].price_amount/100).toLocaleString('uk-UA')}} ₴</p><small>Розміри: {{product.variants.map((v:any)=>v.name).join(' · ')}}</small></Link></section><section v-else class="empty-category">Товари цього розділу готуються до імпорту з чинного каталогу.</section></StoreLayout></template>
